import string

def obfuscate_sql(payload):
  alphabet = string.ascii_letters + string.digits + string.punctuation
  obfuscated = ""
  for char in payload:
    if char in alphabet:
      obfuscated += char
    else:
      obfuscated += chr(ord(char) + 1)
  return obfuscated
